def count_words(input_string):
    words = input_string.lower().split()
    word_counts = {}
    for word in words:
        word = word.strip('.,!?;:"\'".')
        word = word.translate(str.maketrans('', '', ''))  # remove punctuation
        word = word.lower()  # convert to lowercase
        if word in word_counts:
            word_counts[word] += 1
        else:
            word_counts[word] = 1
    return word_counts
```

